import{_ as t,o,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Sources, units and signs","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/02.anleitungen/01.quellen-und-einheiten.md"},"headers":[],"relativePath":"adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","filePath":"adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md","lastUpdated":null}'),i={name:"adapter/sourceanalytix/anleitungen/quellen-und-einheiten.md"};function n(s,e,d,u,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sources-units-and-signs" tabindex="-1">Sources, units and signs <a class="header-anchor" href="#sources-units-and-signs" aria-label="Permalink to &quot;Sources, units and signs&quot;">​</a></h1><p><a id="separate-import-feed-one-datapoint"></a></p><h2 id="how-do-i-separate-consumption-from-the-grid-and-feed-in-one-datapoint-with-a-sign" tabindex="-1">How do I separate consumption from the grid and feed-in (one datapoint with a sign)? <a class="header-anchor" href="#how-do-i-separate-consumption-from-the-grid-and-feed-in-one-datapoint-with-a-sign" aria-label="Permalink to &quot;How do I separate consumption from the grid and feed-in (one datapoint with a sign)?&quot;">​</a></h2><p><strong>In short:</strong> SourceAnalytix doesn&#39;t tell consumption from the grid and feed-in apart by the sign. You create two sources: the datapoint itself for consumption, and an alias with the sign flipped for feed-in. Both get &quot;Ignore negative values&quot;, and the feed-in source also gets a price definition with the cost type &quot;Earnings&quot;.</p><p>The direction of a source comes only from the cost type of its price definition. With &quot;Costs&quot;, SourceAnalytix writes consumption and costs (<code>consumed</code>, <code>costs</code>). With &quot;Earnings&quot;, it writes delivery and earnings (<code>delivered</code>, <code>earnings</code>). Without the checkmark, a negative power value is counted as negative energy and lowers the total, because power sources have no reset detection. With &quot;Ignore negative values&quot; ticked, it counts as 0 W.</p><h3 id="how-to-do-it-from-v0-7-0" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>Open the instance settings of SourceAnalytix and add two rows on the &quot;Price definitions&quot; tab, for example <code>Strom Bezug</code> with the cost type &quot;Costs&quot; and <code>Einspeisung</code> with the cost type &quot;Earnings&quot;, both with the unit <code>kWh</code>. For the feed-in, the &quot;Price per unit&quot; is your feed-in tariff per kWh. Saving restarts the adapter.</li><li>Under &quot;Objects&quot;, create an alias for your power datapoint that flips the sign when read (<code>-val</code>), and give it the unit <code>W</code>.</li><li>In the instance settings, switch to the &quot;Overview&quot; tab and click &quot;Add a source&quot;. Choose the original datapoint, the type &quot;Power&quot; and the price <code>Strom Bezug</code>. In the &quot;Calculation&quot; step, under &quot;For experts&quot;, tick &quot;Ignore negative values&quot; and activate the source.</li><li>Create a second source for the alias in the same way, with the price <code>Einspeisung</code> and also with &quot;Ignore negative values&quot;.</li><li>Consumption is then under <code>sourceanalytix.0.&lt;import&gt;.currentYear.consumed</code>, feed-in under <code>sourceanalytix.0.&lt;feedin&gt;.currentYear.delivered</code> and its earnings under <code>…currentYear.earnings</code>.</li></ol><p>For a source that is already running, tick the checkmark in its source detail under &quot;Settings&quot; and click &quot;⚡ Apply&quot;. It takes effect immediately, without a restart.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Without &quot;Ignore negative values&quot;, the feed-in pulls the total of the consumption source back down. The daily consumption then only shows the net balance and can go negative.</p></div><p>If your electricity meter provides two separate meter readings for consumption and feed-in, use those instead, as two sources of the type meter reading. That is more accurate than power, and a meter reading with a sign doesn&#39;t occur: if a meter reading drops, SourceAnalytix treats it as a reset, not as feed-in. Why the meter reading is more accurate is explained under <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a>.</p><p>A dedicated setting that separates consumption and feed-in from a single datapoint is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1272" target="_blank" rel="noreferrer">#1272</a>).</p><p><strong>Up to v0.6.x:</strong> You find the &quot;Ignore negative power values&quot; checkmark in the SourceAnalytix settings of the datapoint (Objects, wrench) under &quot;Calculation settings&quot;.</p><p><strong>See also:</strong> <a href="#track-pv-yield-feed-earnings">How do I track PV yield, feed-in and earnings?</a> · <a href="#sourceanalytix-compute-consumption-meter-reading">Can SourceAnalytix calculate consumption and a meter reading from power (W)?</a> · <a href="./preise-und-kosten#assign-prices-create-custom-tariffs">How do I assign prices and create my own tariffs (e.g. heat pump)?</a></p><p><a id="unit-datapoint-kwh-wh-m3"></a></p><h2 id="which-unit-do-i-set-on-the-datapoint-kwh-instead-of-wh-m3-instead-of-liters" tabindex="-1">Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)? <a class="header-anchor" href="#which-unit-do-i-set-on-the-datapoint-kwh-instead-of-wh-m3-instead-of-liters" aria-label="Permalink to &quot;Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)?&quot;">​</a></h2><p><strong>In short:</strong> On the source, you set the unit the datapoint actually delivers. &quot;Detect automatically&quot; is usually enough. The unit you see the values in comes from the price definition. SourceAnalytix converts from Wh to kWh or from l to m³ itself.</p><p>Both units and all conversions are listed in the table under <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Which units are supported (energy, volume, weight, length)?</a>.</p><h3 id="how-to-do-it-from-v0-7-0-1" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-1" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>When you create a source, the wizard shows the line &quot;Detected from the datapoint: …&quot; in the &quot;Unit&quot; step. Choose the unit the datapoint counts in. If the detected unit is right, leave it.</li><li>In the &quot;Price&quot; step, you can only choose price definitions whose unit matches. The others are greyed out and carry the note &quot;other unit&quot;.</li><li>For an existing source, change the unit in its source detail under &quot;Settings&quot; in the &quot;Unit&quot; field and click &quot;⚡ Apply&quot;.</li><li>If SourceAnalytix doesn&#39;t detect a unit, the &quot;Problems&quot; tab shows &quot;Unit missing or not recognised&quot;. Use &quot;Fix&quot; to choose it right there.</li></ol><p>Typical mistakes:</p><ul><li><strong>Meter reading, but labeled <code>W</code>:</strong> SourceAnalytix takes the value for a power and sums it up over time. This produces absurdly high values. Choose <code>Wh</code> or <code>kWh</code>.</li><li><strong>Power, but labeled <code>Wh</code> or <code>kWh</code>:</strong> SourceAnalytix takes every value for a meter reading. Choose <code>W</code> or <code>kW</code>.</li><li><strong><code>Wh</code> and <code>kWh</code> mixed up:</strong> All values are too high or too low by a factor of 1,000.</li></ul><h3 id="why-kwh-shows-up-instead-of-m3" tabindex="-1">Why kWh shows up instead of m³ <a class="header-anchor" href="#why-kwh-shows-up-instead-of-m3" aria-label="Permalink to &quot;Why kWh shows up instead of m³&quot;">​</a></h3><p>SourceAnalytix shows all values in the unit of the price definition. If you see kWh even though your gas meter delivers m³, the price definition you chose has the unit <code>kWh</code>. For gas, create a separate price definition with the unit <code>m³</code> and the price per m³, and choose it on the source. SourceAnalytix converts liters and cubic meters into each other, but not m³ of gas into kWh. From v0.6.2, a source with <code>m³</code> and a price definition in <code>kWh</code> doesn&#39;t start at all, and the log says <code>Unit m³ of &lt;datapoint&gt; cannot be converted to unit kWh of price definition &lt;name&gt;</code>.</p><p>A conversion from m³ of gas to kWh is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/6" target="_blank" rel="noreferrer">#6</a>).</p><h3 id="if-you-change-the-unit-later" tabindex="-1">If you change the unit later <a class="header-anchor" href="#if-you-change-the-unit-later" aria-label="Permalink to &quot;If you change the unit later&quot;">​</a></h3><p>A new unit on the source or in the price definition applies from the next value. SourceAnalytix doesn&#39;t convert what is already stored: the total, the start values, and the values of the current and past periods. If the unit was wrong before, total and consumption are therefore still wrong after the change. Correct them afterwards with &quot;Align meter reading&quot; and repair the costs as described under <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correct wrong values</a>.</p><p><strong>Up to v0.6.x:</strong> You set the unit in the SourceAnalytix settings of the datapoint under &quot;Select Unit&quot;. The default is &quot;Detect automatically&quot;. How to get there is described under <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix for a datapoint?</a>.</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#start-values-unit">Start values and their unit</a> · <a href="./../fehlerbehebung/log-meldungen#error-unit-not-supported-no">&quot;unit not supported&quot; / &quot;No unit defined&quot; error</a></p><p><a id="sourceanalytix-compute-consumption-meter-reading"></a></p><h2 id="can-sourceanalytix-calculate-consumption-and-a-meter-reading-from-power-w" tabindex="-1">Can SourceAnalytix calculate consumption and a meter reading from power (W)? <a class="header-anchor" href="#can-sourceanalytix-calculate-consumption-and-a-meter-reading-from-power-w" aria-label="Permalink to &quot;Can SourceAnalytix calculate consumption and a meter reading from power (W)?&quot;">​</a></h2><p><strong>In short:</strong> Yes. SourceAnalytix multiplies each power value by the time until the next value and adds the result to its own total. From that it produces consumption and costs for day, week, month, quarter and year, in the energy unit of the price definition, for example kWh.</p><p>The total (<code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>) starts at 0 on activation. So it shows the energy since activation, not the reading of your electricity meter. How accurate it is depends on how often the device sends. The first value after activation and after every restart of SourceAnalytix only serves as a starting point. There is no reset detection for power sources, and you don&#39;t need any start values.</p><h3 id="how-to-do-it-from-v0-7-0-2" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-2" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>In the instance settings, click &quot;Add a source&quot; on the &quot;Overview&quot; tab and choose the datapoint with the power.</li><li>In the &quot;Type&quot; step, choose &quot;Power&quot;. For the units <code>W</code> and <code>kW</code>, the wizard already suggests it.</li><li>In the &quot;Price&quot; step, choose a price definition with <code>Wh</code>, <code>kWh</code> or <code>MWh</code>. Other units are greyed out.</li><li>Under &quot;For experts&quot; in the &quot;Calculation&quot; step, you find &quot;Average power values&quot; and &quot;Ignore negative values&quot;. What they do is explained under <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">If you only have a power value</a>.</li><li>In the &quot;Start values&quot; step, only &quot;Count from now&quot; is available. Enter a name and activate the source.</li></ol><p>If you still want to tie the total to a real meter, use the &quot;Align meter reading&quot; action. It sets the total, and the values of the current periods stay the same. Because power is only an estimate, the two drift apart again afterwards. The &quot;Meter swapped&quot; action doesn&#39;t exist for power sources.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>If the device or the Wi-Fi goes down, SourceAnalytix extrapolates the last value over the whole outage. You can prevent that with &quot;Maximum gap between power values (minutes)&quot; in the source detail under &quot;Settings&quot; (from v0.7.0). If a power source doesn&#39;t report a value for a long time, the &quot;Problems&quot; tab shows &quot;Power source has not reported for a long time&quot;.</p></div><p><strong>See also:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a> · <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a> · <a href="./../referenz/einstellungen#source-types-exist-meter-power">Which source types are there (meter, power)?</a></p><p><a id="track-pv-yield-feed-earnings"></a></p><h2 id="how-do-i-track-pv-yield-feed-in-and-earnings" tabindex="-1">How do I track PV yield, feed-in and earnings? <a class="header-anchor" href="#how-do-i-track-pv-yield-feed-in-and-earnings" aria-label="Permalink to &quot;How do I track PV yield, feed-in and earnings?&quot;">​</a></h2><p><strong>In short:</strong> Each meter becomes its own source: the inverter&#39;s total yield and the feed-in meter. In each case, use the meter reading in kWh that only goes up, and a price definition with the cost type &quot;Earnings&quot;. SourceAnalytix then writes delivery and earnings instead of consumption and costs.</p><table tabindex="0"><thead><tr><th>What you want to track</th><th>Datapoint</th><th>Price definition</th></tr></thead><tbody><tr><td>PV yield</td><td>Total yield of the inverter in kWh</td><td>Cost type &quot;Earnings&quot;. If you don&#39;t want to see money, leave &quot;Costs&quot; off on the source.</td></tr><tr><td>Feed-in and earnings</td><td>Feed-in meter of your electricity meter</td><td>Cost type &quot;Earnings&quot;, &quot;Price per unit&quot; = feed-in tariff per kWh</td></tr><tr><td>Grid consumption</td><td>Import meter of your electricity meter</td><td>Cost type &quot;Costs&quot;</td></tr></tbody></table><p>The values are then under <code>sourceanalytix.0.&lt;device&gt;.currentYear.delivered</code>, and the earnings under <code>…currentYear.earnings</code>. In the source detail, the columns are called &quot;Delivery&quot; and &quot;Earnings&quot;.</p><h3 id="how-to-do-it-from-v0-7-0-3" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0-3" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>On the &quot;Price definitions&quot; tab, add a row with the cost type &quot;Earnings&quot; and the unit <code>kWh</code>. Saving restarts the adapter.</li><li>Click &quot;Add a source&quot; on the &quot;Overview&quot; tab and choose the total counter. The wizard flags datapoints that look like a daily value (&quot;heute&quot;, &quot;today&quot;, &quot;daily&quot;) with &quot;daily counter&quot;.</li><li>Choose the type &quot;Meter reading&quot; and, in the &quot;Price&quot; step, the new price definition.</li><li>In the &quot;Start values&quot; step, &quot;Count from now&quot; is right if the periods should count from today. If the yield since the start of the day or month should count too, choose &quot;Include consumption since the start of the period&quot; and enter the meter readings at the start of the period. How to do that is described under <a href="./../erste-schritte/erster-zaehler#start-values-unit">What do I enter for the start values (and in which unit)?</a>.</li><li>Enter a name and activate the source. For the feed-in meter, repeat the steps.</li></ol><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Don&#39;t use &quot;Yield today&quot; or a similar daily counter. It drops to 0 every night. That only works with reset detection, and at every drop a small part of the yield is missing. More on this under <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Counter that is reset to 0 daily</a>.</p></div><p>If your inverter only provides the instantaneous power, use it as a power source, see <a href="#sourceanalytix-compute-consumption-meter-reading">Can SourceAnalytix calculate consumption and a meter reading from power (W)?</a>. If you only have a grid datapoint with a sign, see <a href="#separate-import-feed-one-datapoint">Separate consumption and feed-in</a> for how to turn it into two sources.</p><p>SourceAnalytix doesn&#39;t calculate self-consumption and self-sufficiency. This is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/643" target="_blank" rel="noreferrer">#643</a>).</p><p><strong>Up to v0.6.x:</strong> You activate the datapoints one by one in the SourceAnalytix settings of the datapoint and choose the price definition there, see <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix for a datapoint?</a>.</p><p><strong>See also:</strong> <a href="./preise-und-kosten#assign-prices-create-custom-tariffs">How do I assign prices and create my own tariffs (e.g. heat pump)?</a> · <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Where do I find my values (daily consumption today/yesterday)?</a></p><p><a id="derive-counter-flow-run-time"></a></p><h2 id="how-do-i-derive-a-counter-from-flow-rate-run-time-or-several-devices" tabindex="-1">How do I derive a counter from flow rate, run time or several devices? <a class="header-anchor" href="#how-do-i-derive-a-counter-from-flow-rate-run-time-or-several-devices" aria-label="Permalink to &quot;How do I derive a counter from flow rate, run time or several devices?&quot;">​</a></h2><p><strong>In short:</strong> With a script. SourceAnalytix evaluates each datapoint on its own, and over time it only sums up power (W) and pulses per minute. For sums, flow rate, run time or fill level, you therefore write your own meter reading with a script that only goes up, in a supported unit, and activate that datapoint.</p><table tabindex="0"><thead><tr><th>Case</th><th>What you do</th></tr></thead><tbody><tr><td>Several phases of one meter</td><td>Use the total counter of the device. If there is none, build the sum of the phase meter readings in kWh with a script.</td></tr><tr><td>Several devices together</td><td>Each device is its own source. If you need the sum as a counter, build it with a script.</td></tr><tr><td>Flow rate (<code>m³/h</code>, <code>l/min</code>)</td><td>Rates are not supported. The script adds rate × time to a volume in <code>m³</code> or <code>l</code>.</td></tr><tr><td>Burner run time</td><td>Time is not supported. The script calculates run time × consumption per hour in <code>l</code> or <code>kWh</code>.</td></tr><tr><td>Burner starts</td><td>From v0.7.0, directly as a meter reading with the unit <code>piece</code>, see <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Pieces and pulses</a>.</td></tr><tr><td>Fill level (e.g. oil tank)</td><td>Don&#39;t use the fill level itself, it drops as you consume. The script only sums up the decreases and leaves out refills.</td></tr></tbody></table><p>A &quot;Sum of all sources&quot; is planned (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/60" target="_blank" rel="noreferrer">#60</a>).</p><p>How to create the script datapoint so that SourceAnalytix finds it is described in the next section under <a href="#use-script-datapoints-unreliable-sources">Script datapoints</a>.</p><h3 id="reset-detection-for-sums" tabindex="-1">Reset detection for sums <a class="header-anchor" href="#reset-detection-for-sums" aria-label="Permalink to &quot;Reset detection for sums&quot;">​</a></h3><p>To SourceAnalytix, a sum is an ordinary meter reading. If a sub-meter is reset, the sum drops. With reset detection switched on, SourceAnalytix treats this like any other reset: it waits for the next value and then keeps counting on top of the old total. How this works is explained under <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The cleanest option is a sum that never drops: the script adds only the increase of each sub-meter since its last value and ignores decreases. SourceAnalytix then doesn&#39;t notice the reset of a sub-meter at all.</p></div><p><strong>See also:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Which units are supported (energy, volume, weight, length)?</a> · <a href="#sourceanalytix-compute-consumption-meter-reading">Can SourceAnalytix calculate consumption and a meter reading from power (W)?</a></p><p><a id="use-script-datapoints-unreliable-sources"></a></p><h2 id="can-i-use-script-datapoints-or-unreliable-sources" tabindex="-1">Can I use script datapoints or unreliable sources? <a class="header-anchor" href="#can-i-use-script-datapoints-or-unreliable-sources" aria-label="Permalink to &quot;Can I use script datapoints or unreliable sources?&quot;">​</a></h2><p><strong>In short:</strong> Yes. Any datapoint can be a source, whether an adapter, a script, an alias or the Simple API writes it. It just has to deliver a number in a supported unit. It doesn&#39;t matter whether the value was written with or without acknowledgment (<code>ack</code>).</p><p>Values from another ioBroker installation first have to arrive as a datapoint on the system running SourceAnalytix, for example via the Simple API or a script.</p><h3 id="script-datapoints" tabindex="-1">Script datapoints <a class="header-anchor" href="#script-datapoints" aria-label="Permalink to &quot;Script datapoints&quot;">​</a></h3><ul><li>Create the datapoint with the type number and the unit in the object, for example <code>kWh</code>. The wizard only shows datapoints with a detected unit under &quot;Matching datapoints&quot;. Without a unit, pick the datapoint via &quot;Select object&quot; and choose the unit in the next step.</li><li>Write a meter reading that only goes up, and don&#39;t reset it to 0 daily.</li><li>From v0.6.2, SourceAnalytix also reads meter readings that arrive as text, such as <code>&quot;12,5&quot;</code>, and from v0.7.0 power values like <code>&quot;1,5&quot;</code> too (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1288" target="_blank" rel="noreferrer">#1288</a>). If the text isn&#39;t a number, the log says <code>Value &quot;…&quot; of &lt;datapoint&gt; is not a number, reading ignored</code>. The &quot;Problems&quot; tab then reports &quot;Datapoint delivers text instead of a number&quot;.</li></ul><h3 id="outliers-and-decimal-places" tabindex="-1">Outliers and decimal places <a class="header-anchor" href="#outliers-and-decimal-places" aria-label="Permalink to &quot;Outliers and decimal places&quot;">​</a></h3><p>SourceAnalytix only filters values through reset detection:</p><ul><li>A drop of up to the &quot;Threshold&quot; counts as measurement noise and is ignored.</li><li>A single low value, such as a brief 0, is discarded as an outlier if the next value is back at the old level.</li><li>A jump upwards is taken over immediately as consumption. There is no filter against that.</li></ul><p>If your source sometimes delivers absurdly high values, filter them beforehand with a script that only writes plausible, non-decreasing values to a datapoint of its own, and activate that one. If a wrong value has already been taken over, correct it as described under <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correct wrong values</a>.</p><p>Many decimal places in the source are not a problem. You set how many SourceAnalytix outputs on the source under &quot;For experts&quot; with &quot;Decimals for consumption&quot; and &quot;Decimals for costs&quot;.</p><p><strong>Up to v0.6.1:</strong> SourceAnalytix doesn&#39;t calculate datapoints that deliver numbers as text. From v0.6.2, it reads them (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1255" target="_blank" rel="noreferrer">#1255</a>).</p><p><strong>See also:</strong> <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#so-many-decimals">So many decimals</a> · <a href="./../fehlerbehebung/log-meldungen#source-delivers-text-instead-number">Text instead of a number</a></p>',72)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
